#!/usr/bin/env python3
"""Write dx/bfi_crt_gen.h's kCrtHlsl (CRT-Standalone's pattern stage and the passes after it, generated by
tools/crt-handoff/gen_crt_hlsl.py) as HLSL for the Vulkan layer's crt.hlsl: crtgen.py <bfi_crt_gen.h> <out.hlsl>.
The constant buffer gets a Vulkan binding (8, set 0); nothing else changes."""
import re, sys
s = open(sys.argv[1], encoding='utf-8').read()
i = s.index('static const char kCrtHlsl[] =')
j = s.index(';\n// the passes after', i)
lines = []
for l in s[i:j].splitlines()[1:]:
    m = re.match(r'^"(.*)\\n"$', l.strip())
    if m: lines.append(m.group(1).replace('\\"', '"').replace('\\\\', '\\'))
t = '\n'.join(lines) + '\n'
t, n = re.subn(r'cbuffer CrtParams : register\(b1\)', '[[vk::binding(8, 0)]] cbuffer CrtParams', t)
if n != 1: raise SystemExit('constant buffer not found')
open(sys.argv[2], 'w', encoding='utf-8').write('// Written by vulkan/tools/crtgen.py from dx/bfi_crt_gen.h -- do not edit by hand.\n' + t)
